{
  "name": "seo-master",
  "description": "Complete SEO + GEO + AEO playbook for 2026 — multi-engine indexing, framework-aware (Next.js/React), structured data, agent-backend map.",
  "author": {"name": "shihabshahrier", "url": "https://github.com/shihabshahrier"}
}

{
  "hooks": {
    "SessionStart": [{
      "matcher": "startup|resume",
      "hooks": [{
        "type": "command",
        "command": "echo 'seo-master skill available. /seo-master [site]. Steps: detect stack, map AI indexes, audit, fix (indexing -> schema -> content -> titles -> moat). See skills/seo-master/SKILL.md.'",
        "timeout": 5,
        "statusMessage": "Loading seo-master..."
      }]
    }]
  }
}

{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "seo-master",
  "description": "Complete SEO + GEO + AEO playbook for 2026.",
  "owner": {"name": "shihabshahrier", "url": "https://github.com/shihabshahrier"},
  "plugins": [{
    "name": "seo-master",
    "description": "Battle-tested SEO + GEO + AEO playbook: multi-engine indexing, Next.js/React implementation, structured data, agent-backend map.",
    "source": "./",
    "category": "developer-tools"
  }]
}
